#!/usr/bin/env bash
# Removes everything generated by builds and deploys. `icp deploy` recreates it.
# Stops the local network first: its state lives in .icp/cache.
set -euo pipefail
cd "$(dirname "$0")/.."
icp network stop >/dev/null 2>&1 || true
rm -rf target frontend/dist frontend/src/bindings frontend/node_modules frontend/.vite .icp/cache
echo "Clean. Rebuild with: icp network start -d && icp deploy --identity anonymous"
